using System;
using System.Linq;
using System.Globalization;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace PiStudio {
public static partial class ColorLogic {
    static double Encode(double x){return x<=.0031308?12.92*x:1.055*Math.Pow(x,1/2.4)-.055;}
    public static double[] ToOklch(string hex){var c=Parse(hex);double r=Channel(c.R),g=Channel(c.G),b=Channel(c.B),l=Math.Pow(.4122214708*r+.5363325363*g+.0514459929*b,1/3.0),m=Math.Pow(.2119034982*r+.6806995451*g+.1073969566*b,1/3.0),s=Math.Pow(.0883024619*r+.2817188376*g+.6299787005*b,1/3.0);double a=1.9779984951*l-2.428592205*m+.4505937099*s,bb=.0259040371*l+.7827717662*m-.808675766*s;return new[]{.2104542553*l+.793617785*m-.0040720468*s,Math.Sqrt(a*a+bb*bb),(Math.Atan2(bb,a)*180/Math.PI+360)%360};}
    static double[] LinearLch(double l,double c,double h){double a=c*Math.Cos(h*Math.PI/180),b=c*Math.Sin(h*Math.PI/180),ll=l+.3963377774*a+.2158037573*b,mm=l-.1055613458*a-.0638541728*b,ss=l-.0894841775*a-1.291485548*b;ll=ll*ll*ll;mm=mm*mm*mm;ss=ss*ss*ss;return new[]{4.0767416621*ll-3.3077115913*mm+.2309699292*ss,-1.2684380046*ll+2.6097574011*mm-.3413193965*ss,-.0041960863*ll-.7034186147*mm+1.707614701*ss};}
    public static string Oklch(double l,double c,double h){bool mapped;return Oklch(l,c,h,out mapped);}
    public static string Oklch(double l,double c,double h,out bool mapped){if(double.IsNaN(l)||double.IsInfinity(l)||double.IsNaN(c)||double.IsInfinity(c)||double.IsNaN(h)||double.IsInfinity(h)||l<0||l>1||c<0||c>.5)throw new ArgumentException("OKLCH requires L 0–1, C 0–0.5 and a finite hue.");h=(h%360+360)%360;var rgb=LinearLch(l,c,h);mapped=rgb.Any(x=>x<-.000001||x>1.000001);if(mapped){double lo=0,hi=c;for(int i=0;i<24;i++){double mid=(lo+hi)/2;if(LinearLch(l,mid,h).All(x=>x>=0&&x<=1))lo=mid;else hi=mid;}rgb=LinearLch(l,lo,h);}return Hex(System.Drawing.Color.FromArgb((int)Math.Round(Math.Max(0,Math.Min(1,Encode(rgb[0])))*255),(int)Math.Round(Math.Max(0,Math.Min(1,Encode(rgb[1])))*255),(int)Math.Round(Math.Max(0,Math.Min(1,Encode(rgb[2])))*255)));}
    public static string FormatColor(string hex,string format){var c=Parse(hex);if(format=="RGB")return c.R+" "+c.G+" "+c.B;if(format=="HSL")return string.Format(CultureInfo.InvariantCulture,"{0:0.###} {1:0.###} {2:0.###}",c.GetHue(),c.GetSaturation()*100,c.GetBrightness()*100);var lch=ToOklch(hex);return string.Format(CultureInfo.InvariantCulture,"{0:0.######} {1:0.######} {2:0.######}",lch[0],lch[1],lch[2]);}
    public static string ParseFormat(string text,string format,out bool mapped){mapped=false;var parts=(text??"").Split(new[]{' ',',','\t'},StringSplitOptions.RemoveEmptyEntries);if(parts.Length!=3)throw new ArgumentException("Enter three numbers separated by spaces.");double[] v=new double[3];for(int i=0;i<3;i++)if(!double.TryParse(parts[i],NumberStyles.Float,CultureInfo.InvariantCulture,out v[i])||double.IsNaN(v[i])||double.IsInfinity(v[i]))throw new ArgumentException("Enter finite numbers using a decimal point.");if(format=="RGB"){if(v.Any(x=>x<0||x>255||x!=Math.Floor(x)))throw new ArgumentException("RGB channels must be whole numbers from 0 to 255.");return Hex(System.Drawing.Color.FromArgb((int)v[0],(int)v[1],(int)v[2]));}if(format=="HSL"){if(v[0]<0||v[0]>360||v[1]<0||v[1]>100||v[2]<0||v[2]>100)throw new ArgumentException("HSL requires hue 0–360 and saturation/lightness 0–100.");return Hsl(v[0],v[1]/100,v[2]/100);}if(format!="OKLCH")throw new ArgumentException("Unknown color format.");return Oklch(v[0],v[1],v[2],out mapped);}
    public static Palette Import(string json){try{var d=new JavaScriptSerializer().DeserializeObject(json) as Dictionary<string,object>;if(d==null||!d.ContainsKey("colors")||(d.ContainsKey("version")&&(!(d["version"] is int)||(int)d["version"]!=1)))throw new ArgumentException("Unsupported palette version.");var colors=d["colors"] as Dictionary<string,object>;var locks=d.ContainsKey("locks")?d["locks"] as Dictionary<string,object>:null;var p=new Palette {Name=(string)d["name"],Seed=(string)d["seed"],Dark=(string)d["mode"]=="dark"};if((string)d["mode"]!="light"&&(string)d["mode"]!="dark")throw new ArgumentException("Invalid palette mode.");for(int i=0;i<5;i++){p.Colors[i]=Normalize((string)colors[Tokens[i]]);if(locks!=null)p.Locks[i]=(bool)locks[Tokens[i]];}Validate(p);if(string.IsNullOrWhiteSpace(p.Name))throw new ArgumentException("Palette name is required.");return p;}catch(Exception e){throw new ArgumentException("Invalid palette JSON: "+e.Message);}}
}
}

